// src/pages/Result.jsx
import React, { useEffect, useState, useRef } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import Button from "../components/common/Button";
import { useUI } from "../context/UIContext";
import styles from "../Result.module.css";
import { saveToSheet } from "../components/utils/googleSheetLogger";
import DcsSurvey from "./DcsSurvey";
import Stepper from "../components/common/Stepper";

const Result = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { setHeroData, allAnswers } = useUI();
  const { finalData, topicKey } = location.state || {};

  // 狀態管理
  const [isFlowModalOpen, setIsFlowModalOpen] = useState(false);
  const [isSurveyOpen, setIsSurveyOpen] = useState(false);
  const [isSurveyCompleted, setIsSurveyCompleted] = useState(false);

  // 語音播放控制器
  const synthRef = useRef(window.speechSynthesis);

  // 🚀 圖片防呆機制：如果 sdm.js 尚未回傳，直接給預設網址以防按鈕消失
  const chartUrl =
    finalData?.flowChart ||
    "https://sdm-5cbs.onrender.com/assets/images/default.png";

  useEffect(() => {
    if (!finalData) return;

    // 如果使用者正點開「互動問卷」，同步將上方的 Hero 區塊狀態做對應更新，防止排版錯位
    if (isSurveyOpen) {
      setHeroData({
        step: 3,
        currentStep: 3,
        imageUrl:
          "https://web-production-fbb7b.up.railway.app/static/helperinside.png",
        title: "最後步驟：填寫決策評估",
        description:
          "請協助點選下方的互動問卷，讓我們了解這項工具對您的輔助成效喔！",
      });
      return; // 跳過下方的結果語音播放
    }

    // 🎯 正常顯示結果時：提取結果卡的標題與純文字內容
    const tempDiv = document.createElement("div");
    tempDiv.innerHTML = finalData.description || "";
    const pureDescription = tempDiv.textContent || tempDiv.innerText || "";

    const userName = allAnswers.userName || "您";
    const narration = `${userName}，我已為您整理好：`;

    // 最終語音文字：建議方案名稱 + 方案內文
    const speechText = `${narration}${finalData.title}。${pureDescription}`;

    // 同步更新上方 Hero 區塊組件
    setHeroData({
      step: 3,
      currentStep: 3,
      imageUrl:
        "https://web-production-fbb7b.up.railway.app/static/helperinside.png",
      title: "第三步驟：評估結果建議",
      description: speechText,
    });

    // 自動播放語音邏輯
    if (synthRef.current) {
      synthRef.current.cancel();
    }

    const timer = setTimeout(() => {
      const utterance = new SpeechSynthesisUtterance(speechText);
      utterance.lang = "zh-TW";
      utterance.rate = 1.0;
      synthRef.current.speak(utterance);
    }, 300);

    return () => {
      clearTimeout(timer);
      if (synthRef.current) synthRef.current.cancel();
    };
  }, [setHeroData, finalData, isSurveyOpen, allAnswers.userName]);

  const handleSurveyComplete = async (finalDcsAnswers) => {
    setIsSurveyCompleted(true);
    setIsSurveyOpen(false);

    try {
      const logData = {
        date: new Date().toLocaleDateString(),
        userName: allAnswers.userName,
        birthDate: allAnswers.birthday || allAnswers.birthDate,
        selectedTopic: allAnswers.selectedTopic,
        details: JSON.stringify(allAnswers.answers),
        finalResult: finalData.title,
        dcsScore: JSON.stringify(finalDcsAnswers),
      };
      await saveToSheet(logData);
    } catch (error) {
      console.error("資料同步失敗", error);
    }
  };

  if (!finalData) return null;

  return (
    <div className={styles.container}>
      {/* 頂部導航進度條：強制固定在最後的 FINISH 階段 */}
      <div className={styles.headerArea}>
        <div className={styles.stepperWrapper}>
          <Stepper
            topicKey={topicKey}
            currentId="FINISH"
            isConflictMode={false}
          />
        </div>
      </div>

      <div className={styles.spacer}></div>

      {/* 滿版問卷 Overlay */}
      {isSurveyOpen && (
        <DcsSurvey
          onComplete={handleSurveyComplete}
          onClose={() => setIsSurveyOpen(false)}
        />
      )}

      {/* 建議方案結果卡片 */}
      <div className={styles.resultCard}>
        <h2 className={styles.resultTitle}>{finalData.title}</h2>
        <hr className={styles.divider} />
        <div
          className={styles.description}
          dangerouslySetInnerHTML={{ __html: finalData.description }}
        />
      </div>

      {/* 互動區塊 */}
      <div className={styles.interactiveGroup}>
        {/* 🚀 修正後的重點：改用 chartUrl 做安全判定，保證按鈕一定會出現！ */}
        {chartUrl && (
          <button
            onClick={() => setIsFlowModalOpen(true)}
            className={styles.secondaryPinkButton}
            style={{ marginBottom: "20px", width: "100%" }} // 加上美化間距
          >
            🔍 查看您的預計治療流程
          </button>
        )}

        <div
          className={`${styles.surveyCard} ${isSurveyCompleted ? styles.surveyCardCompleted : ""}`}
        >
          <p
            className={`${styles.surveyTitle} ${isSurveyCompleted ? styles.surveyTitleCompleted : ""}`}
          >
            {isSurveyCompleted
              ? "✅ 填寫完成！醫療團隊已收到您的回饋"
              : "最後一步：請填寫決策評估問卷"}
          </p>
          <p className={styles.surveySubText}>
            {isSurveyCompleted
              ? "感謝您協助我們提升醫療輔助品質。"
              : "填寫此問卷能幫助我們了解這項工具對您的幫助。"}
          </p>
          {!isSurveyCompleted && (
            <button
              onClick={() => setIsSurveyOpen(true)}
              className={styles.primaryPinkButton}
            >
              點此開始互動問卷
            </button>
          )}
        </div>
      </div>

      {/* 底部按鈕區 */}
      <div className={styles.footerButtonArea}>
        <Button
          style={{ width: "100%", height: "50px", borderRadius: "25px" }}
          onClick={() => navigate("/selection")}
          isDisabled={!isSurveyCompleted}
        >
          {isSurveyCompleted ? "完成並回首頁" : "請先完成上方問卷以解鎖結束"}
        </Button>
      </div>

      {/* 流程圖彈出視窗 (Modal) */}
      {isFlowModalOpen && (
        <div
          onClick={() => setIsFlowModalOpen(false)}
          className={styles.modalOverlay}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            className={styles.modalContent}
          >
            <div className={styles.modalHeader}>
              <h3 className={styles.modalTextTitle}>您的預計治療流程</h3>
              <button
                onClick={() => setIsFlowModalOpen(false)}
                className={styles.closeButton}
              >
                ✕
              </button>
            </div>
            <div className={styles.modalBody}>
              <img
                src={chartUrl}
                alt="治療流程圖"
                style={{ width: "100%", height: "auto" }}
              />
            </div>
            <div className={styles.modalFooter}>
              <button
                className={styles.modalPrimaryButton}
                onClick={() => window.print()}
              >
                🖨️ 列印 / 儲存 PDF
              </button>
              <button
                className={styles.modalSecondaryButton}
                onClick={() => setIsFlowModalOpen(false)}
              >
                關閉
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Result;
